const gr = g * Math.PI / 180;
const c2 = aLen * aLen + bLen * bLen - 2 * aLen * bLen * Math.cos(gr);
const cLen = Math.sqrt(Math.max(c2, 0));
const scale = 70;
const Cx = 300, Cy = 380;
