H.text("Generalizes Pythagoras; the -2ab*cosC term corrects for the angle between a and b.", 24, 52, { color: H.colors.sub, size: 13 });
H.path([[Cx, Cy], [Ax, Ay], [Bx, By]], { color: H.colors.ink, width: 3, fill: "rgba(110,168,254,0.10)", close: true });
H.line(Cx, Cy, Ax, Ay, { color: H.colors.accent, width: 4 });
H.line(Cx, Cy, Bx, By, { color: H.colors.good, width: 4 });
H.line(Ax, Ay, Bx, By, { color: H.colors.violet, width: 4 });
const r = 44; const pts = [];
for (let i = 0; i <= 18; i++) { const ang = -gr * i / 18; pts.push([Cx + r * Math.cos(ang), Cy + r * Math.sin(ang)]); }
